-- Convert agency IDs and their foreign key columns to PostgreSQL UUIDs.
BEGIN;

-- Map every existing agency ID to a UUID generated by PostgreSQL so related
-- rows can keep pointing to the same agency after the key changes.
CREATE TEMP TABLE _agency_id_uuid_map (
  old_id TEXT PRIMARY KEY,
  new_id UUID NOT NULL DEFAULT gen_random_uuid()
) ON COMMIT DROP;

INSERT INTO _agency_id_uuid_map (old_id)
SELECT id::text
FROM public.agencies;

ALTER TABLE public.agency_customization
  DROP CONSTRAINT "agency_customization_agencyId_fkey";
ALTER TABLE public.agency_map
  DROP CONSTRAINT "agency_map_agencyAccountId_fkey";

UPDATE public.agency_customization AS target
SET "agencyId" = mapping.new_id::text
FROM _agency_id_uuid_map AS mapping
WHERE target."agencyId" = mapping.old_id;

UPDATE public.agency_map AS target
SET "agencyAccountId" = mapping.new_id::text
FROM _agency_id_uuid_map AS mapping
WHERE target."agencyAccountId" = mapping.old_id;

UPDATE public.agencies AS target
SET id = mapping.new_id::text
FROM _agency_id_uuid_map AS mapping
WHERE target.id::text = mapping.old_id;

ALTER TABLE public.agencies
  ALTER COLUMN id TYPE UUID USING id::uuid,
  ALTER COLUMN id SET DEFAULT gen_random_uuid();

ALTER TABLE public.agency_customization
  ALTER COLUMN "agencyId" TYPE UUID USING "agencyId"::uuid;

ALTER TABLE public.agency_map
  ALTER COLUMN "agencyAccountId" TYPE UUID USING "agencyAccountId"::uuid;

ALTER TABLE public.agency_customization
  ADD CONSTRAINT "agency_customization_agencyId_fkey"
  FOREIGN KEY ("agencyId") REFERENCES public.agencies(id)
  ON DELETE CASCADE ON UPDATE CASCADE;

ALTER TABLE public.agency_map
  ADD CONSTRAINT "agency_map_agencyAccountId_fkey"
  FOREIGN KEY ("agencyAccountId") REFERENCES public.agencies(id)
  ON DELETE CASCADE ON UPDATE CASCADE;

COMMIT;
